def max_sum_list(lists):
    """The program dawnr proved in `t`, written in Python (checked against `t`, not itself proved).

    requires len(lists) > 0
    ensures  exists i in [0, len(lists)) . lists[i] == r
    ensures  forall j in [0, len(lists)) . sum(lists[j]) <= sum(r)

    Outside its `requires` it raises ValueError: nothing was proved there.
    """
    if not (_t_ints(lists, 2)):
        raise TypeError('max_sum_list: `lists` must be a list of lists of integers; nothing was proved for anything else')
    lists = _t_tuple(lists)
    if not _t_requires(lists):
        raise ValueError('max_sum_list: this input is outside what was proved (requires len(lists) > 0)')
    _t_result = _t_core(lists)
    return _t_list(_t_result)

def _t_core(lists):
    r = lists[0]
    i = 1
    # invariant: 0 <= i
    # invariant: i <= len(lists)
    # invariant: exists k in [0, i) . lists[k] == r
    # invariant: forall j in [0, i) . sum(lists[j]) <= sum(r)
    # decreases: len(lists) - i
    while (i < len(lists)):
        if (_t_fn_sum(lists[i]) > _t_fn_sum(r)):
            r = lists[i]
        i = (i + 1)
    return r

def _t_fn_sum(s):
    return (0 if (len(s) == 0) else (s[0] + _t_fn_sum(s[1:len(s)])))

def _t_requires(lists):
    try:
        return bool((len(lists) > 0))
    except (IndexError, ZeroDivisionError):   # a `requires` with no value here admits nothing
        return False

def _t_tuple(v):
    return tuple(_t_tuple(x) for x in v) if isinstance(v, (list, tuple)) else v

def _t_ints(v, depth):
    if depth == 0:
        return isinstance(v, int) and not isinstance(v, bool)
    return isinstance(v, (list, tuple)) and all(_t_ints(x, depth - 1) for x in v)

def _t_list(v):
    return [_t_list(x) for x in v] if isinstance(v, tuple) else v
